package com.codepilot1c.core.edt.development;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.concurrent.TimeUnit;
import org.eclipse.core.resources.*;
import org.eclipse.core.runtime.jobs.Job;
import com.google.gson.*;

/** Read-only project inspection. A marker snapshot is never a runtime acceptance. */
public final class ChangeCheckService {
    public interface Backend {Map<String,Object> capture(String project,List<String> files)throws Exception;Map<String,Object> run(String id)throws Exception;}
    public static class NativeBackend implements Backend {
        public Map<String,Object> capture(String name,List<String> explicit)throws Exception {
            IProject project=ResourcesPlugin.getWorkspace().getRoot().getProject(name);if(!project.isOpen() || project.getLocation()==null)throw new IllegalArgumentException("Open local project required");
            if(!project.isSynchronized(IResource.DEPTH_INFINITE))project.refreshLocal(IResource.DEPTH_INFINITE,null);Path path=project.getLocation().toFile().toPath().toRealPath();
            Map<String,Object> out=new LinkedHashMap<>();out.put("project",name);out.put("project_location",path.toString());
            List<Map<String,Object>> files=new ArrayList<>();String gitState="available",branch="";Set<String> candidates=new TreeSet<>();
            if(explicit!=null && !explicit.isEmpty()){candidates.addAll(explicit);gitState="explicit_files";}
            else try{String prefix=git(path,"rev-parse","--show-prefix").trim();String status=git(path,"status","--porcelain=v1","-z","--untracked-files=all","--",".");String[] entries=status.split("\\u0000");for(int i=0;i<entries.length;i++){String entry=entries[i];if(entry.length()<4)continue;String rel=entry.substring(3);if(prefix.isEmpty() || rel.startsWith(prefix)){candidates.add(rel.substring(prefix.length()));}if(entry.charAt(0)=='R' || entry.charAt(0)=='C')i++;}branch=git(path,"branch","--show-current").trim();}catch(Exception e){gitState="unavailable";}
            if(candidates.size()>2000)throw new IllegalStateException("More than 2000 changed files; pass an explicit scope");
            files=inspectFiles(path,candidates);
            List<Map<String,Object>> markers=new ArrayList<>();for(IMarker m:project.findMarkers(IMarker.PROBLEM,true,IResource.DEPTH_INFINITE)){if(markers.size()>=10000)throw new IllegalStateException("Too many diagnostics");markers.add(Map.of("path",m.getResource().getProjectRelativePath().toString(),"line",m.getAttribute(IMarker.LINE_NUMBER,0),"severity",m.getAttribute(IMarker.SEVERITY,0),"message",m.getAttribute(IMarker.MESSAGE,"")));}
            markers.sort(Comparator.comparing(x->new Gson().toJson(x)));boolean busy=false;for(Job j:Job.getJobManager().find(null))if((j.belongsTo(ResourcesPlugin.FAMILY_AUTO_BUILD)||j.belongsTo(ResourcesPlugin.FAMILY_MANUAL_BUILD))&&j.getState()!=Job.NONE)busy=true;
            out.put("files",files);out.put("diagnostics",markers);out.put("builders_busy",busy);out.put("git_state",gitState);out.put("branch",branch);return out;
        }
        private String git(Path dir,String... args)throws Exception {List<String> cmd=new ArrayList<>(List.of("git","-c","core.fsmonitor=false","-C",dir.toString()));cmd.addAll(List.of(args));ProcessBuilder builder=new ProcessBuilder(cmd).redirectError(ProcessBuilder.Redirect.DISCARD);builder.environment().keySet().removeIf(k->k.startsWith("GIT_"));builder.environment().put("GIT_OPTIONAL_LOCKS","0");Process p=builder.start();var reader=java.util.concurrent.CompletableFuture.supplyAsync(()->{try{return p.getInputStream().readNBytes(2*1024*1024+1);}catch(Exception e){throw new java.util.concurrent.CompletionException(e);}});if(!p.waitFor(15,TimeUnit.SECONDS)){p.destroyForcibly();throw new IllegalStateException("Git inspection timed out");}byte[] bytes=reader.get(2,TimeUnit.SECONDS);if(p.exitValue()!=0||bytes.length>2*1024*1024)throw new IllegalStateException("Git inspection unavailable/too large");return new String(bytes,StandardCharsets.UTF_8);}
        public Map<String,Object> run(String id)throws Exception{return DevelopmentRunService.getInstance().status(id,0);}
    }
    private final Path storage;private final Backend backend;private static final Gson JSON=new Gson();
    public ChangeCheckService(Path storage,Backend backend)throws Exception{this.storage=storage;this.backend=backend;Files.createDirectories(storage);}
    public static ChangeCheckService workspace()throws Exception{return new ChangeCheckService(ResourcesPlugin.getWorkspace().getRoot().getLocation().toFile().toPath().resolve(".metadata/.plugins/com.codepilot1c.core/checks"),new NativeBackend());}
    public Map<String,Object> baseline(String project,List<String> files)throws Exception{Map<String,Object> snapshot=backend.capture(project,files);String id=saveSnapshot("baseline",snapshot);return Map.of("baseline_id",id,"project",project,"diagnostics",rows(snapshot,"diagnostics").size(),"builders_busy",snapshot.get("builders_busy"),"writes_database",false);}
    public Map<String,Object> changes(String project,List<String> files,String baseline,String runId)throws Exception {
        Map<String,Object> now=new LinkedHashMap<>(backend.capture(project,files)),before=baseline==null?null:load(baseline,project);if(before!=null&&!Objects.equals(before.get("project_location"),now.get("project_location")))throw new IllegalArgumentException("Baseline project location changed");
        List<Map<String,Object>> markers=rows(now,"diagnostics"),added=before==null?new ArrayList<>():new ArrayList<>(markers),removed=new ArrayList<>();
        if(before!=null){Set<String> old=new HashSet<>();for(var r:rows(before,"diagnostics"))old.add(markerKey(r));Set<String> current=new HashSet<>();for(var r:markers)current.add(markerKey(r));added.removeIf(x->old.contains(markerKey(x)));for(var r:rows(before,"diagnostics"))if(!current.contains(markerKey(r)))removed.add(r);}
        Map<String,String> hashes=new HashMap<>();if(before!=null)for(var row:rows(before,"files"))hashes.put((String)row.get("path"),(String)row.get("sha256"));List<Map<String,Object>> currentFiles=new ArrayList<>();for(var original:rows(now,"files")){Map<String,Object> row=new LinkedHashMap<>(original);currentFiles.add(row);boolean git="available".equals(now.get("git_state"));row.put("changed",git?true:before==null?"unknown_without_baseline":!hashes.containsKey(row.get("path"))?"unknown_not_in_baseline":"omitted".equals(row.get("sha256")) || "omitted".equals(hashes.get(row.get("path")))?"unknown_hash_omitted":!Objects.equals(hashes.get(row.get("path")),row.get("sha256")));}
        now.put("files",currentFiles);now.put("baseline_builders_busy",before!=null && Boolean.TRUE.equals(before.get("builders_busy")));now.put("new_diagnostics_known",before!=null && !Boolean.TRUE.equals(before.get("builders_busy")) && !Boolean.TRUE.equals(now.get("builders_busy")));now.put("diagnostics_added",added);now.put("diagnostics_removed",removed);if(baseline!=null)now.put("baseline_id",baseline);
        if(runId!=null){Map<String,Object> run=backend.run(runId);if(!project.equals(run.get("project")))throw new IllegalArgumentException("Scenario belongs to another project");now.put("scenario",AgentBrief.run(run,0));}
        String id=saveSnapshot("report",now);return brief(id,now);
    }
    @SuppressWarnings("unchecked") private static List<Map<String,Object>> rows(Map<String,Object> map,String name){return (List<Map<String,Object>>)map.getOrDefault(name,List.of());}
    private Map<String,Object> brief(String id,Map<String,Object> map){List<Map<String,Object>> diagnostics=rows(map,"diagnostics"),added=rows(map,"diagnostics_added");long errors=diagnostics.stream().filter(x->((Number)x.get("severity")).intValue()==IMarker.SEVERITY_ERROR).count();long newErrors=added.stream().filter(x->((Number)x.get("severity")).intValue()==IMarker.SEVERITY_ERROR).count();boolean known=Boolean.TRUE.equals(map.get("new_diagnostics_known"));Map<String,Object> out=new LinkedHashMap<>();out.put("check_id",id);out.put("project",map.get("project"));out.put("git_state",map.get("git_state"));out.put("branch",map.get("branch"));out.put("inspected_files",rows(map,"files").size());out.put("changed_files",!Boolean.TRUE.equals(map.get("new_diagnostics_known")) && !"available".equals(map.get("git_state"))?"unknown_without_baseline":rows(map,"files").stream().filter(x->Boolean.TRUE.equals(x.get("changed"))).count());long unknown=rows(map,"files").stream().filter(x->x.get("changed") instanceof String).count();long knownChanged=rows(map,"files").stream().filter(x->Boolean.TRUE.equals(x.get("changed"))).count();out.put("known_changed_files",knownChanged);out.put("unknown_file_changes",unknown);out.put("file_comparison_complete",unknown==0 && !"unavailable".equals(map.get("git_state")));if(unknown>0)out.put("changed_files","unknown_incomplete_comparison");out.put("objects",rows(map,"files").stream().map(x->x.get("object")).filter(Objects::nonNull).distinct().limit(20).toList());out.put("errors",errors);out.put("new_errors",known?newErrors:map.containsKey("baseline_id")?"unknown_builders_running":"unknown_without_baseline");out.put("baseline_builders_busy",map.get("baseline_builders_busy"));out.put("builders_busy",map.get("builders_busy"));out.put("static_verdict",Boolean.TRUE.equals(map.get("builders_busy"))?"builders_running":errors>0?"errors_present":"current_markers_clear");out.put("runtime_verified",false);if(map.containsKey("scenario"))out.put("scenario",map.get("scenario"));out.put("diagnostics_sample",diagnostics.stream().limit(5).map(x->{var r=new LinkedHashMap<>(x);String msg=String.valueOf(r.get("message"));if(msg.length()>400){r.put("message",msg.substring(0,400));r.put("message_truncated",true);}return r;}).toList());out.put("next_tool","edt_check");out.put("next_actions",List.of("details","start","baseline"));out.put("writes_database",false);return out;}
    public Map<String,Object> details(String project,String id,String section,int offset,int limit)throws Exception{if(offset<0||limit<1||limit>100||!Set.of("files","diagnostics","diagnostics_added","diagnostics_removed").contains(section))throw new IllegalArgumentException("Invalid detail page");Map<String,Object> map=load(id,project);List<Map<String,Object>> rows=rows(map,section);int from=Math.min(offset,rows.size()),to=(int)Math.min((long)offset+limit,rows.size());return Map.of("check_id",id,"section",section,"total",rows.size(),"items",rows.subList(from,to),"has_more",to<rows.size(),"offset",offset);}
    @SuppressWarnings("unchecked") private Map<String,Object> load(String id,String project)throws Exception{if(id==null||!id.matches("check-[0-9a-f-]{36}"))throw new IllegalArgumentException("Invalid check ID");Path file=storage.resolve(id+".json");if(Files.isSymbolicLink(file)||Files.size(file)>8*1024*1024)throw new IllegalArgumentException("Invalid check snapshot");Map<String,Object> value=JSON.fromJson(Files.readString(file),LinkedHashMap.class);if(!project.equals(value.get("project")))throw new IllegalArgumentException("Check belongs to another project");return value;}
    private String saveSnapshot(String role,Map<String,Object> value)throws Exception{String id="check-"+UUID.nameUUIDFromBytes((role+":"+JSON.toJson(value)).getBytes(StandardCharsets.UTF_8));save(id,value);return id;}
    private void save(String id,Map<String,Object> value)throws Exception{String text=JSON.toJson(value);if(text.getBytes(StandardCharsets.UTF_8).length>8*1024*1024)throw new IllegalArgumentException("Check exceeds 8 MiB");Path target=storage.resolve(id+".json");if(Files.exists(target)){if(Files.isSymbolicLink(target)||!Files.readString(target,StandardCharsets.UTF_8).equals(text))throw new IllegalStateException("Snapshot identity collision or modified content");return;}Path tmp=Files.createTempFile(storage,"check-",".tmp");try{Files.writeString(tmp,text,StandardCharsets.UTF_8);Files.move(tmp,storage.resolve(id+".json"),StandardCopyOption.ATOMIC_MOVE);}finally{Files.deleteIfExists(tmp);}}
    private static String markerKey(Map<String,Object> r){return JSON.toJson(List.of(r.get("path"),((Number)r.get("line")).intValue(),((Number)r.get("severity")).intValue(),r.get("message")));}
    static List<Map<String,Object>> inspectFiles(Path root,Collection<String> paths)throws Exception {
        if(paths.size()>2000)throw new IllegalArgumentException("Too many files");List<Map<String,Object>> rows=new ArrayList<>();long remaining=64L*1024*1024;
        for(String rel:paths){Path file=root.resolve(rel).normalize();if(rel.isBlank()||Path.of(rel).isAbsolute()||!file.startsWith(root)||Arrays.asList(rel.replace('\\','/').split("/")).contains(".."))throw new IllegalArgumentException("Use project-relative source paths");if(Files.exists(file)&&!file.toRealPath().startsWith(root))throw new IllegalArgumentException("Source link escapes project");String hash="missing",state="absent";long size=0;
            if(Files.isRegularFile(file)){size=Files.size(file);long allowance=Math.min(8L*1024*1024,remaining);hash="omitted";state="omitted_size_limit";
                if(size<=allowance){MessageDigest digest=MessageDigest.getInstance("SHA-256");long read=0;boolean complete=false;try(var in=Files.newInputStream(file)){byte[] buffer=new byte[65536];while(read<=allowance){int n=in.read(buffer,0,(int)Math.min(buffer.length,allowance-read+1));if(n<0){complete=true;break;}read+=n;digest.update(buffer,0,n);}}remaining=Math.max(0,remaining-read);if(complete){hash=HexFormat.of().formatHex(digest.digest());state="hashed";}}
            }
            Map<String,Object> row=new LinkedHashMap<>();row.put("path",rel);row.put("sha256",hash);row.put("hash_state",state);row.put("size_bytes",size);String[] parts=rel.replace('\\','/').split("/");if(parts.length>=3&&parts[0].equals("src"))row.put("object",parts[1]+"/"+parts[2]);rows.add(row);
        }return rows;
    }
}
